SELECT sm.id AS master_id,sm.title,sm.track,sm.disc,sm.album_id,a.name AS album_name FROM song_masters sm JOIN albums a ON a.id=sm.album_id WHERE sm.album_id!='pending-uploads' AND lower(trim(sm.title)) IN ('#0412歌声人形 协议纪录','01 词穷（ nekock · lk remake )','02 オブザーバー（ nekock · lk remake )','03 自我的存在证明（ nekock · lk remake )','04 旋梯（ nekock · lk remake )','05 再、願い。','06 星满归途（純白 p remix )','07 ra in bar ( dos remix )','08 link your world ( mr . guai remix )','09 オブザーバー( yqxp remix )','0と1の世界で、あなたへ','10 reversed whiteness ( necoaloo remix','11 沙塔（ dbrt remix )','12 未来·未来（ ykykyukai remix )','2025拜年纪倒计时bgm-新岁钟鼓','3 晚','a ghost from kaleidos','amplifier,扬声器','beyond the sky','bonus track by suz','colour cast 色相偏移','connect','connect-night drive remix','countinuing','farewell letter to wuqing','i.m.i','layosa','lumos night','lyra·artist version(feat.廖澄奏)','nightwalk','observer','overlap','reflected light','reversed whiteness','sec.1 你会选哪边') ORDER BY sm.title,sm.album_id